package com.chubb.apac.claims.modulith.user.service;
import com.chubb.apac.claims.modulith.user.dto.request.UpdateProfileRequest;import com.chubb.apac.claims.modulith.user.mapper.UserMapper;import com.chubb.apac.claims.modulith.user.model.User;import com.chubb.apac.claims.modulith.user.repository.UserRepository;import com.chubb.apac.claims.modulith.user.service.impl.UserServiceImpl;import org.junit.jupiter.api.*;import org.mockito.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.Optional;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class UserServiceImplTest {@Test void updatesOwnProfile(){UserRepository r=mock(UserRepository.class);User u=new User();u.setId("U1");u.setEmail("a@b.com");u.setFullName("Old");when(r.findById("U1")).thenReturn(Optional.of(u));var s=new UserServiceImpl(r,new UserMapper(),mock(PasswordEncoder.class));var out=s.updateProfile("U1",new UpdateProfileRequest("New","123"));assertThat(out.fullName()).isEqualTo("New");}}
